#pragma once
#include "../PluginProcessor.h"
#include <sstream>
#include <locale>
// UI-thread library; no filesystem work takes place in the audio callback.
class PresetLibrary {
public:
 struct Entry {juce::String key,name,category;int factory=-1;juce::ValueTree state;juce::StringArray tags;};
 juce::Array<Entry> entries;juce::StringArray favourites;juce::String error;
 PresetLibrary(){auto overridePath=juce::SystemStats::getEnvironmentVariable("PLATE140_PRESET_HOME",{});directory=overridePath.isNotEmpty()?juce::File(overridePath):juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory).getChildFile("Aulamix/PLATE140");reload();}
 static bool validState(const juce::ValueTree&v){if(v.getType().toString()!="PLATE140"||int(v.getProperty("version",1))!=1||v.getNumChildren()!=20)return false;
  constexpr float minimum[]={0,.5f,.5f,.5f,0,0,0,0,-100,0,20,-12,200,-12,0,0,0,0,0,0};constexpr float maximum[]={2,5.5f,5.5f,5.5f,2,2,5,100,100,1,2000,12,20000,12,1,10,250,100,1,1};juce::StringArray found;
  for(auto c:v){if(c.getType().toString()!="PARAM")return false;auto id=c.getProperty("id").toString();int index=-1;for(int j=0;j<20;++j)if(id==platebank::ids[j])index=j;if(index<0||found.contains(id))return false;auto text=c.getProperty("value").toString().trim();std::istringstream stream(text.toStdString());stream.imbue(std::locale::classic());double value=0;stream>>value;if(!stream||!stream.eof()||!std::isfinite(value)||value<minimum[index]||value>maximum[index])return false;found.add(id);}return true;}
 static juce::StringArray tagsFor(const juce::ValueTree&state){auto get=[&](const char*id,float fallback){for(auto child:state)if(child.getProperty("id").toString()==id)return float(child.getProperty("value"));return fallback;};
  int p=int(get("plate_select",0));auto rt=get(platebank::ids[p+1],2);juce::StringArray tags;if(rt<=1.2f)tags.add("Short");if(rt>=2.8f)tags.add("Long");if(get("eq_high_gain",0)<-1)tags.add("Dark");if(get("eq_high_gain",0)>1)tags.add("Bright");return tags;}
 static juce::ValueTree factoryState(int i){juce::ValueTree v("PLATE140");v.setProperty("version",1,nullptr);auto&p=platebank::presets[i];for(int n=0;n<20;++n){juce::ValueTree child("PARAM");child.setProperty("id",platebank::ids[n],nullptr);child.setProperty("value",p.values[size_t(n)],nullptr);v.addChild(child,-1,nullptr);}return v;}
 void reload(){entries.clear();favourites.clear();error.clear();readOnly=false;for(int i=0;i<platebank::count;++i){auto&p=platebank::presets[i];auto v=factoryState(i);auto tags=tagsFor(v);tags.add(p.category);entries.add({"factory:"+juce::String(i+1),p.name,p.category,i,v,tags});}
  auto file=directory.getChildFile("library.xml");if(!file.existsAsFile())return;auto xml=juce::XmlDocument::parse(file);if(!xml||!xml->hasTagName("PLATE140LIBRARY")||xml->getIntAttribute("version")!=1){readOnly=true;error="Biblioteca invalida: arquivo preservado.";return;}
  for(auto* c=xml->getFirstChildElement();c;c=c->getNextElement()){if(c->hasTagName("FAV"))favourites.addIfNotAlreadyThere(c->getStringAttribute("key"));if(c->hasTagName("USER")){auto* data=c->getChildByName("PLATE140");if(!data)continue;auto v=juce::ValueTree::fromXml(*data);if(!validState(v))continue;auto tags=tagsFor(v);tags.add("User");entries.add({c->getStringAttribute("key"),c->getStringAttribute("name"),"User",-1,v,tags});}}
 }
 bool persist(){if(readOnly)return false;error.clear();if(!directory.createDirectory().wasOk()){error="Nao foi possivel criar a pasta de presets.";return false;}juce::XmlElement root("PLATE140LIBRARY");root.setAttribute("version",1);for(auto& key:favourites)root.createNewChildElement("FAV")->setAttribute("key",key);for(auto&e:entries)if(e.factory<0){auto*c=root.createNewChildElement("USER");c->setAttribute("key",e.key);c->setAttribute("name",e.name);c->addChildElement(e.state.createXml().release());}
  juce::TemporaryFile temp(directory.getChildFile("library.xml"));if(!root.writeTo(temp.getFile())||!temp.overwriteTargetFileWithTemporary()){error="Falha ao salvar biblioteca; arquivo anterior preservado.";return false;}return true;}
 juce::String saveUser(juce::String name,const juce::ValueTree&state){MutationGuard guard(directory);if(!guard.locked){error="Biblioteca ocupada; tente novamente.";return {};}reload();name=name.trim();if(name.isEmpty()){error="Informe um nome para o preset.";return {}; }if(!validState(state)){error="Estado invalido: nenhum preset foi salvo.";return {}; }juce::String key="user:"+juce::Uuid().toString();auto tags=tagsFor(state);tags.add("User");entries.add({key,name,"User",-1,state.createCopy(),tags});if(!persist()){entries.removeLast();return {};}return key;}
 bool renameUser(const juce::String&key,juce::String name){MutationGuard guard(directory);if(!guard.locked){error="Biblioteca ocupada; tente novamente.";return false;}reload();name=name.trim();if(name.isEmpty())return false;for(auto&e:entries)if(e.key==key&&e.factory<0){auto old=e.name;e.name=name;if(persist())return true;e.name=old;return false;}return false;}
 bool deleteUser(const juce::String&key){MutationGuard guard(directory);if(!guard.locked){error="Biblioteca ocupada; tente novamente.";return false;}reload();for(int i=0;i<entries.size();++i)if(entries.getReference(i).key==key&&entries.getReference(i).factory<0){auto old=entries[i];entries.remove(i);bool fav=favourites.contains(key);favourites.removeString(key);if(persist())return true;entries.insert(i,old);if(fav)favourites.add(key);return false;}return false;}
 bool toggleFavourite(const juce::String&key){MutationGuard guard(directory);if(!guard.locked){error="Biblioteca ocupada; tente novamente.";return false;}reload();bool was=favourites.contains(key);if(was)favourites.removeString(key);else favourites.add(key);if(persist())return true;if(was)favourites.add(key);else favourites.removeString(key);return false;}
 void apply(const Entry&e,PlateProcessor&p){if(e.factory>=0)p.loadPreset(e.factory);else {auto v=e.state.createCopy();v.setProperty("preset_name",e.name,nullptr);v.setProperty("preset_key",e.key,nullptr);p.restoreState(v);}}
private:
 struct MutationGuard{juce::InterProcessLock lock;bool locked;explicit MutationGuard(const juce::File&dir):lock("Aulamix_PLATE140_"+juce::String::toHexString(dir.getFullPathName().hashCode64())),locked(lock.enter(1000)){}~MutationGuard(){if(locked)lock.exit();}};
 juce::File directory;bool readOnly=false;
};
